  '+91 94124 06016', '919412406016', 'Hello VIOR ATELIER, I''m interested in your digital services.',
  'vioratelier7@gmail.com', 'https://vioratelier.com', '[]'::jsonb,
  array['Under ₹25,000','₹25,000 – ₹50,000','₹50,000 – ₹1,00,000','₹1,00,000 – ₹2,50,000','Above ₹2,50,000','Not sure yet']::text[],
  array['As soon as possible','Within 1 month','1 – 3 months','3 months or more','Flexible']::text[],
  'VIOR ATELIER · Crafting Digital Experiences',
