insert into public.services (category_id, title, slug, summary, hero_heading, overview, scope, problems, benefits, deliverables, faqs, image_url, image_alt, sort_order, status, seo_title, seo_description)
values ((select id from public.service_categories where slug = 'design'), 'Website Design & Development', 'website-design-development', 'Business websites, landing pages and custom digital experiences.', 'Websites designed with intent and built to perform.', 'A website is often the first conversation a customer has with your business. We design and build sites that make that conversation clear, credible and easy to act on. Every project starts with your goals and your audience, then moves through considered design, careful development and thorough testing, so the result looks refined and works properly on every screen.',
  array['Business websites','Landing pages','Responsive development','Custom UI/UX design','Website redesign','Performance optimisation']::text[], array['An outdated site that no longer reflects the quality of your business','Visitors who leave because the site is slow or hard to use on a phone','Content you cannot update without calling a developer','A template look that makes you blend in with competitors']::text[], array['A distinctive design shaped around your brand, not a template','Fast, responsive pages that work on every device','Clear structure that guides visitors towards enquiring or buying','A content system you can manage yourself']::text[], array['Discovery session and site map','Visual design for key pages (desktop and mobile)','Responsive front-end development','Content management setup','On-page SEO foundations and analytics setup','Testing across browsers and devices','Launch support and handover walkthrough']::text[], '[{"q": "How long does a website take?", "a": "Timelines depend on scope. A focused landing page can take a couple of weeks; a full business website usually takes longer. We agree a schedule with you before work begins."}, {"q": "Will I be able to update the website myself?", "a": "Yes. We set up a content management system so you can edit text, images and other content without technical knowledge."}, {"q": "Do you redesign existing websites?", "a": "Yes. We can review your current site, keep what works and rebuild the rest with a clearer structure and design."}, {"q": "Is hosting included?", "a": "We can advise on and set up suitable hosting. Ongoing hosting and domain costs depend on the provider you choose."}]'::jsonb,
  null, null, 1, 'published', 'Website Design & Development · VIOR ATELIER', 'Business websites, landing pages and custom digital experiences.');

insert into public.services (category_id, title, slug, summary, hero_heading, overview, scope, problems, benefits, deliverables, faqs, image_url, image_alt, sort_order, status, seo_title, seo_description)
values ((select id from public.service_categories where slug = 'hospitality'), 'QR Code Menu Solutions', 'qr-code-menu-solutions', 'Modern digital menus for restaurants, cafes and hospitality businesses.', 'Digital menus that feel as considered as your service.', 'A QR code menu should feel like part of your venue, not an afterthought. We design mobile-first menu pages that are easy to read at the table, reflect your brand and can be updated in minutes when dishes, prices or availability change.',
  array['Digital restaurant menus','QR code generation','Mobile-friendly menu pages','Category-based menus','Menu item management','Easy menu updates']::text[], array['Printed menus that are costly to reprint whenever prices change','PDF menus that are slow and awkward to read on a phone','Generic menu apps that do not match your brand','No easy way to mark items as unavailable']::text[], array['Update dishes and prices instantly, without reprinting','A menu designed for small screens and quick decisions','Your branding, typography and photography throughout','QR codes ready for tables, counters and takeaway packaging']::text[], array['Menu structure and category planning','Branded, mobile-first menu design','Menu item management for updates','Print-ready QR codes linking to your menu','Setup guidance for staff']::text[], '[{"q": "Do guests need to download an app?", "a": "No. Guests scan the QR code with their phone camera and the menu opens in their browser."}, {"q": "Can we change prices and items ourselves?", "a": "Yes. Menu items, prices and categories can be updated whenever you need."}, {"q": "Can the menu match our brand?", "a": "Yes. The menu uses your colours, typography and imagery so it feels consistent with your venue."}, {"q": "Will the QR code keep working if the menu changes?", "a": "Yes. The QR code points to your menu page, so updates appear without printing new codes."}]'::jsonb,
  null, null, 2, 'published', 'QR Code Menu Solutions · VIOR ATELIER', 'Modern digital menus for restaurants, cafes and hospitality businesses.');

insert into public.services (category_id, title, slug, summary, hero_heading, overview, scope, problems, benefits, deliverables, faqs, image_url, image_alt, sort_order, status, seo_title, seo_description)
values ((select id from public.service_categories where slug = 'growth'), 'SEO Setup & Optimisation', 'seo-setup-optimisation', 'Technical SEO, on-page SEO, search visibility setup and website optimisation.', 'Search foundations, set up properly from the start.', 'Good search visibility starts with solid foundations. We make sure your website is technically sound, clearly structured and correctly connected to the tools search engines use, so your content has the best possible chance to be found. We focus on best practice and transparent reporting. No one can honestly guarantee specific Google rankings, and we never will.',
  array['Technical SEO','On-page SEO','Metadata optimisation','Sitemap and robots.txt','Search Console setup','Google Analytics integration','Image optimisation','Structured data where appropriate']::text[], array['A website that search engines struggle to crawl or understand','Missing or duplicated page titles and descriptions','No visibility into how people find your site','Slow, heavy images that hurt the experience on mobile']::text[], array['A technically sound site that search engines can crawl and index','Clear, relevant metadata for every important page','Search Console and Analytics configured so you can see what is working','Faster pages through image and performance optimisation']::text[], array['Technical SEO audit','Page titles, meta descriptions and headings review','XML sitemap and robots.txt configuration','Google Search Console setup and verification','Google Analytics integration','Image optimisation recommendations or implementation','Structured data (schema) where appropriate','Summary report with prioritised next steps']::text[], '[{"q": "Can you guarantee first-page rankings on Google?", "a": "No. Rankings depend on many factors outside anyone''s control, and no honest provider can guarantee them. We set up strong technical and on-page foundations that give your site the best chance."}, {"q": "How soon will we see results?", "a": "Search engines can take weeks or months to reflect changes. Technical fixes are usually picked up sooner than content-driven growth."}, {"q": "Do you work on websites you did not build?", "a": "Yes. We can audit and improve the SEO setup of an existing website, depending on the platform it uses."}, {"q": "What do we need to provide?", "a": "Access to your website and, ideally, your Google account so we can connect Search Console and Analytics."}]'::jsonb,
  null, null, 3, 'published', 'SEO Setup & Optimisation · VIOR ATELIER', 'Technical SEO, on-page SEO, search visibility setup and website optimisation.');

